  const ts = (tipos || []).map(String);
  if (RELIGIOSA_RE.test(n) || ts.some((t) => TIPOS_RELIGIOSA.includes(t))) return 'religiosa';
  if (ORGAO_RE.test(n) || ts.some((t) => TIPOS_ORGAO.includes(t))) return 'orgao_publico';
